<div class="table-wrapper card"><table><thead><tr><th>Postulante</th><th>Contacto</th><th>Especialidad</th><th>Biografia</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach ($solicitudes as $request): ?><tr><td><strong><?= e($request['nombre'] . ' ' . $request['apellido']) ?></strong><span class="table-profile-description"><?= e($request['usuario']) ?></span></td><td><?= e($request['correo']) ?><span class="table-profile-description"><?= e($request['telefono'] ?: 'Sin telefono') ?></span></td><td><?= e($request['especialidad']) ?></td><td><?= e($request['biografia'] ?: 'Sin biografia') ?></td><td><span class="status status-<?= e($request['estado']) ?>"><?= e($request['estado']) ?></span></td><td><?php if ($request['estado'] === 'pendiente'): ?><form method="post" action="<?= e(app_url('solicitudes-tutor/revisar.php')) ?>"><input type="hidden" name="id_solicitud" value="<?= (int) $request['id_solicitud'] ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn btn-sm btn-primary" name="estado" value="aprobada" type="submit">Aprobar</button><button class="btn btn-sm btn-outline-danger" name="estado" value="rechazada" type="submit">Rechazar</button></form><?php else: ?>-<?php endif; ?></td></tr><?php endforeach; ?><?php if (!$solicitudes): ?><tr><td colspan="6">No hay solicitudes registradas.</td></tr><?php endif; ?></tbody></table></div>
